(function(){
const mount=document.getElementById("kb-sales-hero-workspace");if(!mount||mount.dataset.kbReady==="true")return;mount.dataset.kbReady="true";
"use strict";
const scenarios = [
  { name:"Korisnička podrška",short:"Podrška kupcima",icon:"chat",question:"„Kako beše rešavamo reklamaciju?“",heading:"Pouzdan odgovor, i kada iskusni kolega nije tu.",description:"Dogovoreni postupci i odgovori na ponovljena pitanja ostaju dostupni timu. Svako ima polaznu tačku za sledeći razgovor sa kupcem.",bullets:["Postupci za tipične situacije","Uputstva i prateći dokumenti na istom mestu","Iskustvo tima sačuvano za sledeći put"],category:"Podrška kupcima",title:"Kako rešavamo reklamaciju",intro:"Zabeležite problem, proverite dokumentaciju i dogovorite sledeći korak sa kupcem.",steps:["Zabeležite zahtev kupca","Prikupite račun i fotografije","Prosledite nadležnoj osobi"],note:"Ako nedostaje dokumentacija, prvo zatražite dopunu od kupca.",file:"Postupak reklamacije.pdf",link:"Interna pravila reklamacija",source:"Beleška sa sastanka podrške" },
  { name:"Uvođenje zaposlenih",short:"Ljudi i tim",icon:"users",question:"„Odakle da počnem prvog dana?“",heading:"Dobar početak za novog kolegu. Više prostora za mentora.",description:"Okupite osnovna uputstva, pravila i korake za prve dane. Novi zaposleni dobija jasan put, a mentor se posvećuje onome što traži razgovor.",bullets:["Prvi dani organizovani u jasne celine","Pravila i uputstva koja se lako ponovo otvaraju","Znanje koje ostaje i posle obuke"],category:"Ljudi i tim",title:"Vaš prvi radni dan",intro:"Dobro došli u tim. Ovaj kratki vodič pomaže da se lakše snađete u prvim koracima.",steps:["Upoznajte svoj tim i mentora","Proverite potrebne pristupe","Prođite osnovne procedure"],note:"Za nedoumice koje nisu obuhvaćene vodičem obratite se svom mentoru.",file:"Vodič za nove kolege.pdf",link:"Organizacija tima",source:"Beleške HR tima" },
  { name:"Svakodnevna operativa",short:"Operativa",icon:"list",question:"„Koji je sledeći korak u ovom postupku?“",heading:"Jasan postupak koji prati posao kroz ceo tim.",description:"Zapišite kako se posao obavlja, na šta treba obratiti pažnju i kome se prosleđuje. Manje oslanjanja na pamćenje, više zajedničkog razumevanja.",bullets:["Procedure dostupne kada zatrebaju","Kategorije prema načinu rada vašeg tima","Izmene koje možete da pregledate"],category:"Operativne procedure",title:"Prijem robe, korak po korak",intro:"Proverite isporuku i prateću dokumentaciju pre nego što završite prijem.",steps:["Uporedite isporuku sa dokumentom","Zabeležite eventualna odstupanja","Prosledite potvrdu o prijemu"],note:"U slučaju odstupanja obavestite nadležnu osobu pre završetka prijema.",file:"Kontrolna lista prijema.pdf",link:"Pravila skladišnog poslovanja",source:"Beleška iz operative" }
];
const icon = name => `<svg class="icon" aria-hidden="true"><use href="#kb-sales-i-${name}"/></svg>`;
const stepNotes = ["Prikupite osnovne informacije pre sledećeg koraka.","Povežite relevantne podatke i prateće dokumente.","Nastavite prema dogovorenom postupku vašeg tima."];
function article(s,compact=false){return `<article class="article-content"><div class="article-path">${icon("folder")}${s.category}${icon("chevron")}<span>Uputstva</span></div><div class="article-status"><span class="status-dot"></span>Primer članka<span class="article-read">2 min čitanja</span></div><h3>${s.title}</h3><p class="article-intro">${s.intro}</p><div class="article-divider"></div><h4>Postupak</h4><ol class="article-steps">${s.steps.map((v,i)=>`<li><span>${i+1}</span><div><strong>${v}</strong>${compact?"":`<p>${stepNotes[i]}</p>`}</div></li>`).join("")}</ol><aside class="article-note">${s.note}</aside><div class="article-footer">${icon("clip")}<span>${s.file}</span><span>PDF · primer</span></div></article>`;}
function sources(s){return `<div class="sources-view"><span class="tiny-label">OD IZVORA DO UPUTSTVA</span><h3>Sve počinje onim što već znate.</h3><p>Okupite materijale iz kojih nastaje vaš članak.</p>${[["file",s.source,"Tekst i beleška"],["clip",s.file,"Priloženi dokument"],["link",s.link,"Link do izvora"]].map(([i,title,sub])=>`<div class="source-row">${icon(i)}<div><strong>${title}</strong><span>${sub}</span></div>${icon("check")}</div>`).join("")}<div class="source-help">Izvori ostaju uz članak radi lakšeg pregleda porekla.</div></div>`;}
function versions(){return `<div class="versions-view"><span class="tiny-label">ISTORIJA SADRŽAJA</span><h3>Znate šta se menjalo.</h3><p>Pregledajte raniji tekst, uporedite izmene i vratite sadržaj prethodne verzije.</p>${["Dopunjeno uputstvo","Dodat korak za proveru","Prva verzija članka"].map((v,i)=>`<div class="version-entry"><span class="version-point ${i===0?"current":""}"></span><div><strong>${v}</strong><p>${i===0?"Trenutna verzija":"Prethodna verzija"} · primer</p></div>${i===0?'<span class="version-badge">Aktuelno</span>':icon("history")}</div>`).join("")}<div class="version-diff"><span>+ Jasnije opisan sledeći korak.</span><span>+ Dopunjena napomena za tim.</span></div></div>`;}
const workspaces = {};
function workspace(id,scenarioIndex,activeTab=1){
  const s=scenarios[scenarioIndex],hero=id==="kb-sales-hero-workspace";
  workspaces[id]={scenarioIndex,activeTab};
  document.getElementById(id).innerHTML=`<div class="workspace-top">${icon("book")}<strong>Baza znanja</strong><span class="workspace-top-right">Vaš tim<span class="avatar">VT</span></span></div><div class="workspace-body"><aside class="workspace-sidebar" aria-label="Ilustracija kategorija"><span class="sidebar-label">PROSTOR ZA ZNANJE</span>${[["users","Ljudi i tim",1],["list","Operativa",2],["chat","Podrška kupcima",0]].map(([i,label,n])=>`<div class="sidebar-item ${n===scenarioIndex?"selected":""}">${icon(i)}${label}</div>${n===scenarioIndex?`<div class="sidebar-child active">${icon("file")}<span>${s.title}</span></div><div class="sidebar-child">${icon("file")}Korisna uputstva</div>`:""}`).join("")}<div class="sidebar-bottom">${icon("lock")}Elastyc okruženje</div></aside><div class="workspace-main"><div class="workspace-tabs" role="tablist" aria-label="Istražite prikaz članka">${["Unos i obrada","Sadržaj","Verzije"].map((v,i)=>`<button role="tab" id="${id}-tab-${i}" aria-selected="${activeTab===i}" aria-controls="${id}-panel" tabindex="${activeTab===i?0:-1}" data-tab="${i}" data-workspace="${id}">${v}</button>`).join("")}</div><div class="workspace-panel" id="${id}-panel" role="tabpanel" tabindex="0" aria-labelledby="${id}-tab-${activeTab}">${activeTab===1?article(s,hero):activeTab===0?sources(s):versions()}</div></div></div><div class="workspace-caption"><span class="status-dot"></span>Ilustrativni prikaz · primer sadržaja<span>Web i mobilni workspace</span></div>`;
}
function scenario(index){
  const s=scenarios[index];
  document.querySelectorAll(".kb-sales [data-scenario]").forEach(b=>b.setAttribute("aria-pressed",String(Number(b.dataset.scenario)===index)));
  document.getElementById("kb-sales-scenario-copy").innerHTML=`<span class="scenario-quote">${s.question}</span><h3>${s.heading}</h3><p>${s.description}</p><ul>${s.bullets.map(b=>`<li>${icon("check")}${b}</li>`).join("")}</ul><button class="text-link dark-link" data-open-demo>Pogledajte primer za svoj tim ${icon("arrow")}</button>`;
  workspace("kb-sales-scenario-workspace",index);selectedScenario=index;
}
let selectedScenario=0,priorFocus=null;
workspace("kb-sales-hero-workspace",0);scenario(0);
const dialog=document.getElementById("kb-sales-demo-dialog");
function demoScenario(index){document.querySelectorAll(".kb-sales [data-demo-scenario]").forEach(b=>b.setAttribute("aria-pressed",String(Number(b.dataset.demoScenario)===index)));document.getElementById("kb-sales-dialog-article").innerHTML=article(scenarios[index]);}
function closeDemo(){dialog.close();}
document.addEventListener("click",event=>{
  const anchor=event.target.closest('.kb-sales a[href^="#kb-sales-"]');if(anchor){const target=document.getElementById(anchor.getAttribute("href").slice(1));if(target){event.preventDefault();target.scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});return;}}
  const tab=event.target.closest("[data-tab]");if(tab){const id=tab.dataset.workspace,index=Number(tab.dataset.tab);workspace(id,workspaces[id].scenarioIndex,index);document.getElementById(`${id}-tab-${index}`).focus({preventScroll:true});return;}
  const choice=event.target.closest("[data-scenario]");if(choice){scenario(Number(choice.dataset.scenario));return;}
  const demo=event.target.closest("[data-demo-scenario]");if(demo){demoScenario(Number(demo.dataset.demoScenario));return;}
  if(event.target.closest("[data-open-demo]")){priorFocus=event.target.closest("button");demoScenario(selectedScenario);dialog.showModal();document.body.style.overflow="hidden";return;}
  if(event.target.closest("#kb-sales-close-demo, #kb-sales-finish-demo")){closeDemo();return;}
});
document.addEventListener("keydown",event=>{const tab=event.target.closest("[data-tab]");if(!tab)return;let next=Number(tab.dataset.tab);if(event.key==="ArrowRight")next=(next+1)%3;else if(event.key==="ArrowLeft")next=(next+2)%3;else if(event.key==="Home")next=0;else if(event.key==="End")next=2;else return;event.preventDefault();const id=tab.dataset.workspace;workspace(id,workspaces[id].scenarioIndex,next);document.getElementById(`${id}-tab-${next}`).focus({preventScroll:true});});
dialog.addEventListener("close",()=>{document.body.style.overflow="";priorFocus?.focus({preventScroll:true});});
dialog.addEventListener("click",event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDemo();});
const captureExamples=[
  {label:"Ispričano iskustvo · transkript primera",raw:"Kad kupac prijavi problem, prvo tražimo račun i fotografije. Sve zabeležimo i prosledimo nadležnoj osobi. Ako nešto fali, vratimo se kupcu za dopunu.",title:"Postupak prijema reklamacije",sections:["Kada se primenjuje — kupac prijavljuje problem","Potrebni podaci — račun i fotografije","Koraci — evidentiranje, provera i prosleđivanje","Napomena — zatražiti dopunu kada podaci nedostaju"]},
  {label:"Postojeći dokument · izvod primera",raw:"Vodič za nove kolege.pdf\n\nPrvi dan: upoznavanje sa mentorom, provera pristupa i prolazak kroz osnovne procedure. Za dodatna pitanja obratiti se mentoru.",title:"Vodič za prvi radni dan",sections:["Cilj — lakše snalaženje novog kolege","Priprema — mentor i potrebni pristupi","Prvi koraci — tim, alati i osnovne procedure","Dodatna pitanja — kome se obratiti"]},
  {label:"Povezani izvor · beleška primera",raw:"Interna pravila prijema robe\n\nUporediti isporuku sa dokumentom. Zabeležiti odstupanja i obavestiti nadležnu osobu pre završetka prijema.",title:"Prijem robe, korak po korak",sections:["Obuhvat — provera pristigle isporuke","Dokumentacija — poređenje sa isporukom","Odstupanja — evidentiranje i obaveštavanje","Završetak — potvrda prema internom postupku"]}
];
function renderCapture(index){const e=captureExamples[index];document.querySelectorAll('.kb-sales [data-capture]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.capture)===index)));document.getElementById('kb-sales-capture-content').innerHTML=`<div class="capture-input"><span class="tiny-label">ULAZ · PRIMER</span><strong>${e.label}</strong><p>${e.raw}</p></div><span class="capture-arrow">${icon('arrow')}</span><div class="capture-output"><span class="tiny-label">PREDLOG ZA PREGLED TIMA</span><strong>${e.title}</strong><ol>${e.sections.map(x=>`<li>${x}</li>`).join('')}</ol><span class="review-label">${icon('check')} Sledi: provera i dopuna sadržaja</span></div>`;}
document.querySelectorAll('.kb-sales [data-capture]').forEach(b=>b.addEventListener('click',()=>renderCapture(Number(b.dataset.capture))));renderCapture(0);

})();
